/**
 * mcp/schemas.json: the tools' input schemas as plain JSON Schema, generated by scripts/build.mjs
 * from tools.mjs with TypeBox (a devDependency), so the MCP server needs no TypeBox at runtime.
 * pi builds the same schemas with its own TypeBox when it loads index.ts; scripts/verify-import.mjs
 * and test/mcp.test.mjs check that both match this file.
 */
import path from "node:path";
import { pathToFileURL } from "node:url";

export async function renderSchemas(root) {
  const { Type } = await import("typebox");
  const { TOOLS, buildSchemas } = await import(pathToFileURL(path.join(root, "tools.mjs")).href);
  const schemas = buildSchemas(Type);
  // TypeBox's markers are non-enumerable symbols, so JSON is exactly what the model sees.
  return JSON.stringify(Object.fromEntries(TOOLS.map((t) => [t.name, schemas[t.name]])), null, 2) + "\n";
}
